/** Cold-shell batch acceptance for the overlay materialization experiment. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class ValueStoreOverlayMaterializationTest {
	static final String BUDGET = "rdf4j.lmdb.valueOverlay.maxBytes";

	@TempDir
	File directory;

	static List<Value> terms(int suffix) {
		var vf = SimpleValueFactory.getInstance();
		String lexical = "é/e\u0301/漢字/😀/" + suffix;
		return List.of(vf.createIRI("https://example.org/namespace/" + lexical),
				vf.createBNode("blank-" + suffix), vf.createLiteral(lexical),
				vf.createLiteral("+000" + suffix, XSD.INTEGER),
				vf.createLiteral(lexical, vf.createIRI("urn:custom:datatype:" + suffix)),
				vf.createLiteral(lexical, "nb"),
				vf.createLiteral(lexical, "ar", Literal.BaseDirection.RTL),
				vf.createLiteral(lexical, "en", Literal.BaseDirection.LTR),
				vf.createLiteral(lexical, "en-x-" + "abcdefgh-".repeat(9) + "abcd", Literal.BaseDirection.RTL),
				vf.createLiteral("shared prefix ".repeat(100) + lexical));
	}

	static CompressedValueOverlay.Options options() {
		return new CompressedValueOverlay.Options(64L << 20, 8192, 16, 64 << 10, 1 << 20, true, true);
	}

	static long[] persist(ValueStore store, List<Value> expected) throws Exception {
		long[] ids = new long[expected.size()];
		store.startTransaction(true);
		for (int i = 0; i < ids.length; i++) {
			ids[i] = store.storeValue(expected.get(i));
		}
		store.commit();
		return ids;
	}

	static void assertBatch(ValueStore store, long[] ids, List<Value> expected) throws Exception {
		store.clearCaches();
		LmdbValue[] values = new LmdbValue[ids.length];
		int[] order = new int[ids.length];
		for (int i = 0; i < ids.length; i++) {
			values[i] = store.getLazyValue(ids[i], ValuePosition.OBJECT);
			assertFalse(values[i].isInitialized(), "the batch must exercise decoding, not cached values");
			order[i] = ids.length - 1 - i;
		}
		values[0].getValueStoreRevision().resolveValues(values, order, values.length);
		for (int i = 0; i < ids.length; i++) {
			assertTrue(values[i].isInitialized());
			assertEquals(expected.get(i), values[i]);
			if (!(expected.get(i) instanceof org.eclipse.rdf4j.model.TripleTerm)) {
				assertEquals(expected.get(i).stringValue(), values[i].stringValue());
			}
			if (expected.get(i) instanceof Literal literal) {
				Literal actual = (Literal) values[i];
				assertEquals(literal.getLabel(), actual.getLabel());
				assertEquals(literal.getDatatype(), actual.getDatatype());
				assertEquals(literal.getLanguage(), actual.getLanguage());
				assertEquals(literal.getBaseDirection(), actual.getBaseDirection());
			}
		}
	}

	@Test
	void coldBatchPreservesAllLexicalFormsWithOverlayAndNativeFallback() throws Exception {
		String previous = System.setProperty(BUDGET, "0");
		ValueStore store = new ValueStore(new File(directory, "lexical"),
				new LmdbStoreConfig().setValueOverlayEnabled(true).setInlineLiterals(false));
		try {
			List<Value> expected = new ArrayList<>(terms(17));
			var vf = SimpleValueFactory.getInstance();
			expected.add(vf.createTripleTerm(vf.createIRI("urn:test:subject"), vf.createIRI("urn:test:predicate"),
					vf.createLiteral("triple payload", "nb")));
			long[] ids = persist(store, expected);
			assertBatch(store, ids, expected);
			assertNotNull(store.warmCompressedValueOverlay(options()));
			assertTrue(store.visitRecord(ids[0], r -> assertTrue(r.lexicalByteLength() > 0)));
			assertFalse(store.visitRecord(ids[8], r -> { }), "extended language record uses fallback");
			assertBatch(store, ids, expected);
			store.clearCompressedValueOverlay();
			assertBatch(store, ids, expected);
		} finally {
			store.close();
			restore(previous);
		}
	}

	@Test
	void coldBatchSeesWriterChangesThenCommittedDelta() throws Exception {
		String previous = System.setProperty(BUDGET, "0");
		ValueStore store = new ValueStore(new File(directory, "delta"),
				new LmdbStoreConfig().setValueOverlayEnabled(true).setInlineLiterals(false));
		try {
			long[] old = persist(store, terms(1));
			assertNotNull(store.warmCompressedValueOverlay(options()));
			List<Value> expected = terms(2);
			long[] ids = new long[expected.size()];
			store.startTransaction(true);
			for (int i = 0; i < ids.length; i++) {
				ids[i] = store.storeValue(expected.get(i));
			}
			assertBatch(store, ids, expected);
			store.commit();
			assertBatch(store, ids, expected);
			assertBatch(store, old, terms(1));
		} finally {
			store.close();
			restore(previous);
		}
	}

	@Test
	void coldScalarAndRetainedReaderPreserveOverlayDeltaAndFallback() throws Exception {
		String previous = System.setProperty(BUDGET, "0");
		int[] retainedReads = { 0 };
		ValueStore store = new ValueStore(new File(directory, "scalar"),
				new LmdbStoreConfig().setValueOverlayEnabled(true).setInlineLiterals(false)) {
			@Override
			boolean resolveWithRetainedReader(TxnManager.Txn reader, long id, LmdbValue value,
					ValueStoreRevision.Lazy revision) throws java.io.IOException {
				retainedReads[0]++;
				return super.resolveWithRetainedReader(reader, id, value, revision);
			}
		};
		try {
			List<Value> expected = new ArrayList<>(terms(21));
			var vf = SimpleValueFactory.getInstance();
			expected.add(vf.createTripleTerm(vf.createIRI("urn:scalar:subject"), vf.createIRI("urn:scalar:predicate"),
					vf.createLiteral("triple payload", "nb")));
			long[] ids = persist(store, expected);
			assertScalar(store, ids, expected);
			assertNotNull(store.warmCompressedValueOverlay(options()));
			assertScalar(store, ids, expected);
			try (var scope = store.openValueResolutionScope(); var active = scope.activateForeground()) {
				assertScalar(store, ids, expected);
			}
			assertTrue(retainedReads[0] > 0, "exercise the real retained dictionary-reader route");
			List<Value> delta = terms(22);
			long[] added = new long[delta.size()];
			store.startTransaction(true);
			for (int i = 0; i < added.length; i++) {
				added[i] = store.storeValue(delta.get(i));
			}
			assertScalar(store, added, delta);
			store.commit();
			assertScalar(store, added, delta);
			assertScalar(store, ids, expected);
			store.clearCompressedValueOverlay();
			assertScalar(store, ids, expected);
		} finally {
			store.close();
			restore(previous);
		}
	}

	static void assertScalar(ValueStore store, long[] ids, List<Value> expected) throws Exception {
		store.clearCaches();
		for (int i = 0; i < ids.length; i++) {
			LmdbValue value = store.getLazyValue(ids[i], ValuePosition.OBJECT);
			assertFalse(value.isInitialized());
			value.init();
			assertTrue(value.isInitialized());
			assertEquals(expected.get(i), value);
			if (expected.get(i) instanceof Literal literal) {
				Literal actual = (Literal) value;
				assertEquals(literal.getLabel(), actual.getLabel());
				assertEquals(literal.getDatatype(), actual.getDatatype());
				assertEquals(literal.getLanguage(), actual.getLanguage());
				assertEquals(literal.getBaseDirection(), actual.getBaseDirection());
			}
		}
	}

	static void restore(String previous) {
		if (previous == null) {
			System.clearProperty(BUDGET);
		} else {
			System.setProperty(BUDGET, previous);
		}
	}
}
